/*
 * pvr_pds_pixel_event_gen.h
 *
 * The PDS pixel-event (end-of-tile) program, generated by Mesa 26.2.1's
 * pvr_pds_generate_pixel_event() (pvr_pds_pixel_event_gen.c).
 */
#ifndef PVR_PDS_PIXEL_EVENT_GEN_H
#define PVR_PDS_PIXEL_EVENT_GEN_H

#include <stdint.h>

/* Sample-rate: transfer uses INSTANCE (== 0). */
#define PVR_PDS_PE_SAMPLE_RATE_INSTANCE  0u

/*
 * Build the DOUTU src0 (USC task control) 64-bit word.
 *   execution_address : USC EOT shader byte offset RELATIVE to the USC heap base
 *                       (4-byte aligned; only bits [31:2] are used).
 *   usc_temps         : number of USC temporaries (blocks of 4 dwords).
 *   sample_rate       : PVR_PDS_PE_SAMPLE_RATE_INSTANCE for transfer.
 *   dual_phase        : 0 for transfer.
 */
/*
 * The most temporaries the DOUTU field can express: it is 6 bits of four-temp
 * blocks, so 63 * 4. It does NOT saturate, it wraps -- 253 temporaries is 64
 * blocks, which masks to 0, and the GPU is then told the shader needs no
 * temporaries at all.
 *
 * This function has no way to refuse, so its contract is that the caller has
 * already checked. Every caller today passes a compile-time constant from a
 * hand-written blob, and those are checked with _Static_assert where the
 * constants are defined; a caller with a value from a shader must use the
 * generators in pvr_pds_render_gen.c, which return -1 instead.
 */
#ifndef PVR_PDS_DOUTU_MAX_TEMPS
#define PVR_PDS_DOUTU_MAX_TEMPS 252u  /* 63 blocks * 4 temporaries */
#endif

uint64_t pvr_pds_pe_build_doutu_src0(uint64_t execution_address,
                                     uint32_t usc_temps,
                                     uint32_t sample_rate,
                                     int dual_phase);

/*
 * Generate the pixel-event program.
 *   data_out needs >= 3*num_rt + 1 dwords; code_out needs >= num_rt + 1 dwords.
 *   Both segments are little-endian uint32 arrays.
 * Returns 0 on success, non-zero on bad input.
 */
int pvr_pds_generate_pixel_event_tq(uint64_t doutu_src0,
                                    const uint32_t *emit_words,   /* 2*num_rt dwords */
                                    uint32_t num_rt,
                                    int has_slc_mcu_cache_controls,
                                    uint32_t *data_out,
                                    uint32_t *code_out,
                                    uint32_t *data_size_dw,
                                    uint32_t *code_size_dw);

#endif /* PVR_PDS_PIXEL_EVENT_GEN_H */
